import{c as s,$ as o,Q as n,j as i,g as e,o as r,n as l,m as c}from"./chunks/framework.Ce_49mA8.js";const w=JSON.parse('{"title":"Personal Capital Overview & Philosophy","description":"OmniCraft ERP unified personal finance architecture for master craftsmen — separating personal savings from workshop cash flow and tracking expenses via capital balance delta.","frontmatter":{"title":"Personal Capital Overview & Philosophy","description":"OmniCraft ERP unified personal finance architecture for master craftsmen — separating personal savings from workshop cash flow and tracking expenses via capital balance delta.","datePublished":"2026-10-28","dateModified":"2026-11-19","order":14},"headers":[],"relativePath":"docs/spaces/moy-kapital/overview.md","filePath":"docs/spaces/moy-kapital/overview.md","lastUpdated":1795046400000}'),d={name:"docs/spaces/moy-kapital/overview.md"},p={id:"personal-capital-overview-philosophy",tabindex:"-1"};function u(h,t,g,m,f,y){const a=o("DocIcon");return n(),i("div",null,[e("h1",p,[r(a,{name:"capital"}),t[0]||(t[0]=l(" Personal Capital Overview & Philosophy ",-1)),t[1]||(t[1]=e("a",{class:"header-anchor",href:"#personal-capital-overview-philosophy","aria-label":'Permalink to "Personal Capital Overview & Philosophy"'},"​",-1))]),t[2]||(t[2]=c('<p>Every craft workshop owner, maker, or studio founder eventually faces the same fundamental dilemma: where does the workshop&#39;s money end and personal family finances begin?</p><p>When raw material procurement, workshop rent, utility bills, and personal supermarket groceries are paid from the same bank card, financial visibility collapses. It becomes impossible to tell whether the business generates genuine net profit or merely stays afloat through continuous subsidies from family savings.</p><p>In <strong>OmniCraft ERP</strong>, the <strong>My Capital</strong> workspace is engineered to establish a strict, transparent boundary between business operations and private life. The system eliminates bookkeeping overhead and frees the maker from tedious daily receipt logging.</p><hr><h2 id="comparing-approaches-to-personal-finance" tabindex="-1">Comparing Approaches to Personal Finance <a class="header-anchor" href="#comparing-approaches-to-personal-finance" aria-label="Permalink to &quot;Comparing Approaches to Personal Finance&quot;">​</a></h2><p>Attempting to manage personal finances using rigid workshop logging or, conversely, treating the business cash register as a personal pocket inevitably leads to a financial dead end:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Dimension</th><th style="text-align:left;">Single Pocket Chaos</th><th style="text-align:left;">OmniCraft ERP Framework</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Financial Boundary</strong></td><td style="text-align:left;">Workshop cash and personal funds mixed on one bank card</td><td style="text-align:left;">Two isolated contours: operational workshop and personal capital</td></tr><tr><td style="text-align:left;"><strong>Personal Expense Tracking</strong></td><td style="text-align:left;">Manual daily entry of receipts for coffee, groceries, and travel</td><td style="text-align:left;">Automated expense calculation via capital balance delta</td></tr><tr><td style="text-align:left;"><strong>Wealth Evaluation</strong></td><td style="text-align:left;">Scattered balances across multiple mobile banking apps and wallets</td><td style="text-align:left;">Consolidated net worth dashboard accounting for workshop equity</td></tr><tr><td style="text-align:left;"><strong>Data Confidentiality</strong></td><td style="text-align:left;">Personal savings and investment data risk leaking into shop reports</td><td style="text-align:left;">Physically isolated local database file <code>personal_finance.db</code></td></tr></tbody></table><hr><h2 id="two-contour-principle-workshop-cash-vs-maker-s-pocket" tabindex="-1">Two-Contour Principle: Workshop Cash vs. Maker&#39;s Pocket <a class="header-anchor" href="#two-contour-principle-workshop-cash-vs-maker-s-pocket" aria-label="Permalink to &quot;Two-Contour Principle: Workshop Cash vs. Maker&#39;s Pocket&quot;">​</a></h2><p>The financial architecture of the platform separates money flows into two independent contours:</p><ol><li><strong>Workshop Operational Contour (Production Workspaces):</strong> raw material inventory tracked via moving average cost (MAC), recipe and cutting consumption calculations, work-in-progress batch tracking on the workbench, cash flow ledger (DDS), and finished goods showcase with first-in, first-out (FIFO) shipments.</li><li><strong>Consolidated Capital Contour (My Capital Workspace):</strong> the aggregate net worth of the owner. This includes cash on hand, bank accounts, savings deposits, investment portfolios, equipment outside the workshop, real estate, personal vehicles, and ownership equity across all connected business ventures.</li></ol><div class="info custom-block"><p class="custom-block-title">Physical Database Isolation</p><p>Personal finances are stored in a dedicated, isolated database file <code>personal_finance.db</code>. Records of personal bank accounts, investments, equity shares, and family reserves are physically separated from operational workshop databases (<code>omnicraft_erp.db</code>, <code>workspaces/*.db</code>) and never leak into production audit trails or inventory reports.</p></div><hr><h2 id="mathematical-delta-automated-expenses-without-receipt-tracking" tabindex="-1">Mathematical Delta: Automated Expenses Without Receipt Tracking <a class="header-anchor" href="#mathematical-delta-automated-expenses-without-receipt-tracking" aria-label="Permalink to &quot;Mathematical Delta: Automated Expenses Without Receipt Tracking&quot;">​</a></h2><p>Most personal finance apps demand robotic discipline: opening a smartphone every evening to manually record petty household expenses. In reality, a craftsman&#39;s resolve lasts at most two weeks, after which tracking is abandoned and reported balances drift away from reality.</p><p>In <strong>OmniCraft ERP</strong>, an inverted engineering approach is applied — the <strong>Balance Delta expense calculation method</strong>:</p><div class="formula-hero-card"><div class="formula-card-top"><span class="formula-badge">OmniCraft ERP Engineering Standard</span><div class="formula-heading">Balance Delta Personal Expense Calculation</div></div><div class="formula-equation-box"><div class="math-formula-display"><span class="math-var">Personal Expenses</span><span class="math-op">=</span><span class="math-var">Initial Capital</span><span class="math-op">+</span><span class="math-var">Workshop Profits &amp; Dividends</span><span class="math-op">−</span><span class="math-var">Ending Capital</span></div></div><div class="formula-card-bottom"><p>Simply update actual balances across key bank cards and accounts once or twice a month. The system automatically balances the delta against workshop operations to isolate exact personal consumption without manual receipt entry.</p></div></div><div class="tip custom-block"><p class="custom-block-title">Peace of Mind</p><p>If personal bank balances increase over the reporting period while workshop net profit is verified by finished goods shipments and revenue, your enterprise is growing profitably. If balances deplete, the system flags the unallocated capital outflow long before a cash crisis hits the workshop.</p></div><hr><h2 id="architecture-of-my-capital-tools" tabindex="-1">Architecture of My Capital Tools <a class="header-anchor" href="#architecture-of-my-capital-tools" aria-label="Permalink to &quot;Architecture of My Capital Tools&quot;">​</a></h2><p>The workspace interface is structured as a streamlined five-step management workflow from liquid assets to consolidated net worth:</p><ol class="craft-ordered-list"><li><strong>Accounts &amp; Investments</strong> — liquid cash, bank deposits, and investment securities.</li><li><strong>Property &amp; Materials</strong> — long-term physical assets, machinery, and raw material funds.</li><li><strong>Key Operations</strong> — major personal revenues, capital additions, and private withdrawals.</li><li><strong>My Net Worth</strong> — consolidated net asset dashboard combining private and workshop equity.</li><li><strong>Analytics</strong> — historical wealth trajectory charts and risk allocation inspection.</li></ol><ul class="craft-feature-list"><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"></polyline></svg></span><span><strong>Accounts &amp; Investments:</strong> Central control center for liquid capital. Houses two dedicated sub-tabs: <em>&quot;Accounts &amp; Wallets&quot;</em> (cash, debit cards, deposits, multi-currency, and digital assets) and <em>&quot;Investment Portfolio&quot;</em> (stocks, bonds, debt securities, equity in external projects).</span></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"></polyline></svg></span><span><strong>Property &amp; Materials:</strong> Long-term physical asset registry (specialized machinery outside the shop, co-owned tooling, real estate, vehicles, and private material reserves).</span></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"></polyline></svg></span><span><strong>Key Operations:</strong> Ledger of significant personal income, external capital investments, and major expenditures directly shifting net worth.</span></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"></polyline></svg></span><span><strong>My Net Worth:</strong> Consolidated capital command center uniting personal holdings and operational equity across all connected workshops.</span></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"></polyline></svg></span><span><strong>Analytics:</strong> Wealth trajectory charts, currency basket diversification breakdown, and asset allocation across risk tiers.</span></li></ul><hr><h2 id="two-level-navigation-and-contextual-action-bars" tabindex="-1">Two-Level Navigation and Contextual Action Bars <a class="header-anchor" href="#two-level-navigation-and-contextual-action-bars" aria-label="Permalink to &quot;Two-Level Navigation and Contextual Action Bars&quot;">​</a></h2><p>The space interface follows a canonical two-level information architecture designed for high information density and zero visual clutter:</p><ul><li><strong>Level 1 (Space Navigation Bar):</strong> Located at the very top of the window, exclusively dedicated to clean switching between the five domains. The top bar remains free of orphaned action buttons.</li><li><strong>Level 2 (Contextual Action Bars per Screen):</strong> Utility tools are co-located directly within the screens where they are needed:</li></ul><table tabindex="0"><thead><tr><th style="text-align:left;">Screen</th><th style="text-align:left;">Location</th><th style="text-align:left;">Action Tools</th><th style="text-align:left;">Purpose</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Accounts &amp; Investments</strong></td><td style="text-align:left;">Opposite &quot;Accounts / Investments&quot; tabs</td><td style="text-align:left;"><strong>&quot;Statistics&quot;</strong>, <strong>&quot;Exchange Rates&quot;</strong>, <strong>&quot;Settings&quot;</strong>, <strong>&quot;Docs&quot;</strong></td><td style="text-align:left;">Currency basket breakdown, rate updates, account/investment categories, and liquid capital documentation.</td></tr><tr><td style="text-align:left;"><strong>Property &amp; Materials</strong></td><td style="text-align:left;">Opposite asset category filter capsules</td><td style="text-align:left;"><strong>&quot;🛡️ Check Duplicates &amp; Collisions&quot;</strong>, <strong>&quot;+ Add Asset&quot;</strong>, <strong>&quot;Docs&quot;</strong></td><td style="text-align:left;">Ownership share collision audit (Hamilton method), duplicate resource consolidation, and asset cataloging.</td></tr><tr><td style="text-align:left;"><strong>Key Operations</strong></td><td style="text-align:left;">In the operations table header</td><td style="text-align:left;"><strong>&quot;Docs&quot;</strong></td><td style="text-align:left;">Guidelines for recording personal revenue streams and significant capital expenditures.</td></tr><tr><td style="text-align:left;"><strong>My Net Worth</strong></td><td style="text-align:left;">In the consolidated dashboard header</td><td style="text-align:left;"><strong>&quot;Refresh&quot;</strong>, <strong>&quot;Docs&quot;</strong></td><td style="text-align:left;">Instant net worth recalculation and consolidated wealth structure inspection.</td></tr><tr><td style="text-align:left;"><strong>Analytics</strong></td><td style="text-align:left;">In the trend dynamics header</td><td style="text-align:left;"><strong>&quot;Docs&quot;</strong></td><td style="text-align:left;">Wealth trajectory analytics and historical continuity inspection across closed workspaces.</td></tr></tbody></table><hr><h2 id="regular-audit-of-funds-assets-and-ownership-share-collisions" tabindex="-1">Regular Audit of Funds, Assets, and Ownership Share Collisions <a class="header-anchor" href="#regular-audit-of-funds-assets-and-ownership-share-collisions" aria-label="Permalink to &quot;Regular Audit of Funds, Assets, and Ownership Share Collisions&quot;">​</a></h2><p>In personal capital structures, craftsmen frequently share machinery, studios, and inventory stock across business and personal life (for instance, a laser engraver co-owned with a business partner, or a private vehicle used for commercial deliveries). During multi-space tracking or manual data entry, mathematical share collisions or duplicate resource entries can emerge.</p><p>OmniCraft ERP features a semi-automated fund audit tool that resolves discrepancies without disrupting net worth balances.</p><h3 id="purpose-and-common-discrepancies" tabindex="-1">Purpose and Common Discrepancies <a class="header-anchor" href="#purpose-and-common-discrepancies" aria-label="Permalink to &quot;Purpose and Common Discrepancies&quot;">​</a></h3><p>Regular auditing addresses three practical asset management requirements:</p><ol><li><strong>Ownership Share Normalization (100% Balance):</strong> The sum of personal, manufacturing, and services ownership shares for any shared asset must strictly equal 100.00%. If manual adjustments leave an imbalance (e.g., <code>95%</code> or <code>105%</code>), net worth calculations become distorted.</li><li><strong>Machinery Duplicate Merging:</strong> Eliminating duplicate listings of tools or machines created under slightly different names across separate workspaces.</li><li><strong>Material Inventory Consolidation:</strong> Merging overlapping raw material records while preserving combined quantities and calculated cost prices.</li></ol><h3 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h3><p>The audit tool is accessible whenever assets or materials are registered in the <strong>&quot;Property &amp; Materials&quot;</strong> section.</p><h3 id="step-by-step-procedure-for-fund-collision-audit" tabindex="-1">Step-by-Step Procedure for Fund &amp; Collision Audit <a class="header-anchor" href="#step-by-step-procedure-for-fund-collision-audit" aria-label="Permalink to &quot;Step-by-Step Procedure for Fund &amp; Collision Audit&quot;">​</a></h3><ol><li><strong>Launch the Audit:</strong> In the &quot;My Net Worth&quot; workspace, navigate to the <strong>&quot;Property &amp; Materials&quot;</strong> tab and click the <strong>&quot;🛡️ Check Duplicates &amp; Collisions&quot;</strong> button in the contextual action bar.</li><li><strong>Review Issues in the &quot;Funds &amp; Collisions Audit&quot; Dialog:</strong><ul><li><strong>Clean Ledger:</strong> The system displays a green status message: <strong>&quot;No collisions or duplicates found. All funds are consistent.&quot;</strong>;</li><li><strong>Ownership Share Collisions:</strong> The <strong>&quot;Ownership Share Collisions&quot;</strong> section highlights cards with share sums violating 100% (e.g., <em>&quot;Sum of shares equals 95.0% instead of 100%&quot;</em>). Clicking <strong>&quot;Fix Shares (100%)&quot;</strong> automatically normalizes shares using the Hamilton apportionment method;</li><li><strong>Equipment Duplicates:</strong> The <strong>&quot;Potential Duplicate Equipment&quot;</strong> section pairs duplicate asset records with collision rationales. Clicking <strong>&quot;Merge Duplicates&quot;</strong> consolidates redundant cards into a single master asset record;</li><li><strong>Raw Material Duplicates:</strong> The <strong>&quot;Potential Duplicate Raw Materials&quot;</strong> section identifies matching inventory lines. Clicking <strong>&quot;Merge Duplicates&quot;</strong> combines quantities into a unified stock entry.</li></ul></li><li><strong>Commit Adjustments:</strong> Click <strong>&quot;Close&quot;</strong>. The software immediately recalculates net asset values and updates balance cards across all summary views.</li></ol><div class="tip custom-block"><p class="custom-block-title">Audit Schedule</p><p>Run the collision audit once a month prior to closing your periodic financial statements, and immediately after importing external asset spreadsheets or adjusting partner ownership stakes.</p></div><hr><h2 id="data-privacy-resilient-open-rate-gateways" tabindex="-1">Data Privacy &amp; Resilient Open Rate Gateways <a class="header-anchor" href="#data-privacy-resilient-open-rate-gateways" aria-label="Permalink to &quot;Data Privacy &amp; Resilient Open Rate Gateways&quot;">​</a></h2><p>All financial calculations happen <strong>strictly offline on your local computer</strong>. OmniCraft ERP never transmits your account balances, investments, or asset registries to third-party clouds or tracking servers.</p><p>Currency rates update automatically in seconds without recurring fees or secret API tokens. The program queries reliable public rate gateways directly (European Central Bank, Central Bank of Russia, CoinGecko). When necessary, you can manually adjust any currency exchange rate in seconds or export a formatted prompt for external AI analysis.</p>',44))])}const k=s(d,[["render",u]]);export{w as __pageData,k as default};
